// Graphics.DrawMesh / DrawMeshInstanced / RenderMesh: draws submitted from script, rendered by this frame's cameras (all of them,
// or the one given) with WorldRenderer and dropped when the next frame starts. The overloads below were generated from the Unity
// API signatures and all funnel into SubmitDraw / SubmitInstanced (defaults as documented: layer 0, every camera, submesh 0, cast and
// receive shadows). The block is copied at submission, as Unity does.
using UnityEngine.Rendering;

namespace UnityEngine
{
    public partial class Graphics
    {
        internal static void SubmitDraw(Mesh mesh, int submeshIndex, Material material, MaterialPropertyBlock properties, Matrix4x4 matrix, int layer, Camera camera,
            ShadowCastingMode castShadows, bool receiveShadows, int instance = 0, MaterialPropertyBlock copied = null)
        {
            if (mesh == null) throw new System.ArgumentNullException(nameof(mesh));
            if (material == null) throw new System.ArgumentNullException(nameof(material));
            MaterialPropertyBlock block = copied;
            if (block == null && properties != null && !properties.isEmpty) { block = new MaterialPropertyBlock(); block.CopyFrom(properties); }
            MiniUnity.WorldRenderer.Submit(new MiniUnity.WorldRenderer.Queued
            {
                mesh = mesh, sub = submeshIndex, mat = material, block = block, M = matrix, instance = instance, layer = layer, camera = camera, cast = castShadows, receive = receiveShadows,
            });
        }

        internal static void SubmitInstanced(Mesh mesh, int submeshIndex, Material material, Matrix4x4[] matrices, int count, MaterialPropertyBlock properties,
            ShadowCastingMode castShadows, bool receiveShadows, int layer, Camera camera)
        {
            if (matrices == null) throw new System.ArgumentNullException(nameof(matrices));
            if (count < 0 || count > matrices.Length) throw new System.ArgumentOutOfRangeException(nameof(count), "Count must be in the range of 0 to the length of the matrices array.");
            if (count > 1023) throw new System.ArgumentOutOfRangeException(nameof(count), "Count must be in the range of 0 to 1023.");
            MaterialPropertyBlock block = null;
            if (properties != null && !properties.isEmpty) { block = new MaterialPropertyBlock(); block.CopyFrom(properties); }
            for (int i = 0; i < count; i++) SubmitDraw(mesh, submeshIndex, material, null, matrices[i], layer, camera, castShadows, receiveShadows, i, block);
        }

        public static void RenderMesh(in RenderParams rparams, Mesh mesh, int submeshIndex, Matrix4x4 objectToWorld, Matrix4x4? prevObjectToWorld = null) => SubmitDraw(mesh, submeshIndex, rparams.material, rparams.matProps, objectToWorld, rparams.layer, rparams.camera, rparams.shadowCastingMode, rparams.receiveShadows);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, bool castShadows, bool receiveShadows, bool useLightProbes) => SubmitDraw(mesh, submeshIndex, material, properties, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, (castShadows ? ShadowCastingMode.On : ShadowCastingMode.Off), receiveShadows);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, Transform probeAnchor, bool useLightProbes) => SubmitDraw(mesh, submeshIndex, material, properties, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, castShadows, receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, bool castShadows, bool receiveShadows, bool useLightProbes) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, (castShadows ? ShadowCastingMode.On : ShadowCastingMode.Off), receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, Transform probeAnchor, LightProbeUsage lightProbeUsage, LightProbeProxyVolume lightProbeProxyVolume) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, castShadows, receiveShadows);
        public static void DrawMeshInstanced(Mesh mesh, int submeshIndex, Material material, Matrix4x4[] matrices, int count, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, int layer, Camera camera, LightProbeUsage lightProbeUsage, LightProbeProxyVolume lightProbeProxyVolume) => SubmitInstanced(mesh, submeshIndex, material, matrices, count, properties, castShadows, receiveShadows, layer, camera);
        public static void DrawMeshInstanced(Mesh mesh, int submeshIndex, Material material, System.Collections.Generic.List<Matrix4x4> matrices, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, int layer, Camera camera, LightProbeUsage lightProbeUsage, LightProbeProxyVolume lightProbeProxyVolume) => SubmitInstanced(mesh, submeshIndex, material, matrices?.ToArray(), matrices?.Count ?? 0, properties, castShadows, receiveShadows, layer, camera);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer) => SubmitDraw(mesh, 0, material, null, Matrix4x4.TRS(position, rotation, Vector3.one), layer, null, ShadowCastingMode.On, true);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera) => SubmitDraw(mesh, 0, material, null, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, ShadowCastingMode.On, true);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex) => SubmitDraw(mesh, submeshIndex, material, null, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, ShadowCastingMode.On, true);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties) => SubmitDraw(mesh, submeshIndex, material, properties, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, ShadowCastingMode.On, true);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, bool castShadows) => SubmitDraw(mesh, submeshIndex, material, properties, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, (castShadows ? ShadowCastingMode.On : ShadowCastingMode.Off), true);
