        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows) => SubmitDraw(mesh, submeshIndex, material, properties, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, castShadows, receiveShadows);
        public static void DrawMesh(Mesh mesh, Vector3 position, Quaternion rotation, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, Transform probeAnchor) => SubmitDraw(mesh, submeshIndex, material, properties, Matrix4x4.TRS(position, rotation, Vector3.one), layer, camera, castShadows, receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer) => SubmitDraw(mesh, 0, material, null, matrix, layer, null, ShadowCastingMode.On, true);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera) => SubmitDraw(mesh, 0, material, null, matrix, layer, camera, ShadowCastingMode.On, true);
