        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, bool castShadows) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, (castShadows ? ShadowCastingMode.On : ShadowCastingMode.Off), true);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, bool castShadows, bool receiveShadows) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, (castShadows ? ShadowCastingMode.On : ShadowCastingMode.Off), receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, castShadows, true);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, castShadows, receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, Transform probeAnchor) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, castShadows, receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, Transform probeAnchor, bool useLightProbes) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, castShadows, receiveShadows);
        public static void DrawMesh(Mesh mesh, Matrix4x4 matrix, Material material, int layer, Camera camera, int submeshIndex, MaterialPropertyBlock properties, ShadowCastingMode castShadows, bool receiveShadows, Transform probeAnchor, LightProbeUsage lightProbeUsage) => SubmitDraw(mesh, submeshIndex, material, properties, matrix, layer, camera, castShadows, receiveShadows);
        public static void DrawMeshInstanced(Mesh mesh, int submeshIndex, Material material, Matrix4x4[] matrices) => SubmitInstanced(mesh, submeshIndex, material, matrices, matrices?.Length ?? 0, null, ShadowCastingMode.On, true, 0, null);
        public static void DrawMeshInstanced(Mesh mesh, int submeshIndex, Material material, Matrix4x4[] matrices, int count) => SubmitInstanced(mesh, submeshIndex, material, matrices, count, null, ShadowCastingMode.On, true, 0, null);
        public static void DrawMeshInstanced(Mesh mesh, int submeshIndex, Material material, Matrix4x4[] matrices, int count, MaterialPropertyBlock properties) => SubmitInstanced(mesh, submeshIndex, material, matrices, count, properties, ShadowCastingMode.On, true, 0, null);
        public static void DrawMeshInstanced(Mesh mesh, int submeshIndex, Material material, Matrix4x4[] matrices, int count, MaterialPropertyBlock properties, ShadowCastingMode castShadows) => SubmitInstanced(mesh, submeshIndex, material, matrices, count, properties, castShadows, true, 0, null);
